package com.lordescanor.botforge;

import android.os.Bundle;
import android.widget.FrameLayout;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import com.google.android.material.bottomnavigation.BottomNavigationView;
public class DashboardActivity extends androidx.fragment.app.FragmentActivity{FrameLayout content;BottomNavigationView nav;public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_dashboard);content=findViewById(R.id.content);nav=findViewById(R.id.navigation);nav.getMenu().add(0,1,0,"الرئيسية").setIcon(android.R.drawable.ic_menu_view);nav.getMenu().add(0,2,1,"النسخ").setIcon(android.R.drawable.ic_menu_save);nav.getMenu().add(0,3,2,"البروفايل").setIcon(android.R.drawable.ic_menu_myplaces);nav.getMenu().add(0,4,3,"About").setIcon(android.R.drawable.ic_menu_info_details);nav.getMenu().add(0,5,4,"الإعدادات").setIcon(android.R.drawable.ic_menu_preferences);nav.setOnNavigationItemSelectedListener(i->{show(i.getItemId());return true;});nav.setSelectedItemId(1);}void show(int id){androidx.fragment.app.Fragment f; if(id==1)f=new HomeFragment();else if(id==2)f=new BotsFragment();else if(id==3)f=new ProfileFragment();else if(id==4)f=new AboutFragment();else f=new SettingsFragment();getFragmentManager();getSupportFragmentManager().beginTransaction().replace(R.id.content,f).commit();} }
